def _ode(self, xi, S, p, u):
    """Malara right-hand side, with dimensionless groups derived from `u`."""
    _, dim = self._physics(u)
    return _ode_system(xi, S, dim)

def _bc(self, Sa, Sb, p, u):
    """Malara boundary conditions, with groups derived from `u`."""
    _, dim = self._physics(u)
    y_T2_in = max(u[2], 1e-20)
    return _boundary_conditions(Sa, Sb, dim, y_T2_in, self.BCs)

def _create_reset_events(self):
    """Create reset events for all vials based on the replacement times.

    Raises
    ------
    ValueError : If reset_times is not valid.
    """

    replacement_times = self.replacement_times
    self.events = []

    # no replacement
    if replacement_times is None:
        return

    # a single time is used for all vials (numbers.Real also covers numpy scalars)
    if isinstance(replacement_times, numbers.Real):
        replacement_times = [[replacement_times]] * 4

    # a flat list of times is used for all vials
    elif isinstance(replacement_times, (list, tuple)) and all(
        isinstance(t, numbers.Real) for t in replacement_times
    ):
        replacement_times = [list(replacement_times)] * 4

    elif isinstance(replacement_times, np.ndarray) and replacement_times.ndim == 1:
        replacement_times = [replacement_times.tolist()] * 4

    # otherwise one list of times per vial
    elif len(replacement_times) != 4:
        raise ValueError(
            "replacement_times must be a single value or a list with the same length as the number of vials"
        )

    # create the internal events
    self.events = [
        self._create_reset_event_vial(i, ts)
        for i, ts in enumerate(replacement_times)
    ]

def __init__(
    self, detection_efficiency=1.0, detection_threshold=None, func_efficiency=None
):

    # backwards compatibility: pathsim-chem accepted a callable here
    if callable(detection_efficiency):
        if func_efficiency is not None:
            raise ValueError(
                "Pass the efficiency function as 'func_efficiency' only, "
                "not also as 'detection_efficiency'"
            )
        warnings.warn(
            "Passing a callable as 'detection_efficiency' is deprecated, "
            "use 'func_efficiency' instead",
            DeprecationWarning,
            stacklevel=2,
        )
        func_efficiency = detection_efficiency
        detection_efficiency = 1.0

    # input validation
    if detection_efficiency < 0:
        raise ValueError(
            f"'detection_efficiency' must be non-negative but is {detection_efficiency}"
        )
    if detection_threshold is not None and detection_threshold < 0:
        raise ValueError(
            f"'detection_threshold' must be non-negative but is {detection_threshold}"
        )
    if func_efficiency is not None and not callable(func_efficiency):
        raise ValueError(
            f"'func_efficiency' must be callable but is {func_efficiency}"
        )

    # store parameters
    self.detection_efficiency = detection_efficiency
    self.detection_threshold = detection_threshold
    self.func_efficiency = func_efficiency

    super().__init__(func=self._eval)

def _efficiency(self, concentration):
    """Detection efficiency at a given concentration."""

    # below the detection limit nothing is detected
    if (
        self.detection_threshold is not None
        and concentration < self.detection_threshold
    ):
        return 0.0

    if self.func_efficiency is not None:
        return self.func_efficiency(concentration)

    return self.detection_efficiency

def _eval(self, flux_in, flow_rate):
    concentration = flux_in / flow_rate if flow_rate > 0 else 0.0

    signal = self._efficiency(concentration) * concentration
    flux_out = flux_in

    return (flux_out, signal)

